PRODUCTION_SOURCE = '"""\nOLA-037\nOracle Post-Persistence Lineage Cycle Coordinator\n\nCanonical boundary between a completed persisted acquisition cycle and OLA-036.\n\nPurpose:\n- require explicit successful persistence evidence before lineage advancement\n- require the exact canonical observations produced by the completed cycle\n- require persisted count equality with the supplied canonical cohort\n- bind cycle completion time to OLA-036 lineage advancement\n- preserve fail-closed behavior before any lineage mutation\n- return one immutable coordination receipt\n\nThis contract does not perform acquisition or persistence itself.\nIt does not interpret intelligence, score signals, alert, hand off to Q Series,\nauthorize trading, place orders, move funds, or mutate portfolios.\n\nOracle remains permanently read-only.\n"""\n\nfrom __future__ import annotations\n\nfrom dataclasses import dataclass\nfrom datetime import datetime, timezone\nfrom hashlib import sha256\nimport json\nfrom typing import Any, Iterable\n\nfrom .oracle_live_acquisition_lineage_cycle_bridge import (\n    LiveAcquisitionLineageCycleContractError,\n    LiveAcquisitionLineageCycleInvariantError,\n    LiveAcquisitionLineageCycleReceipt,\n    OracleLiveAcquisitionLineageCycleBridge,\n)\nfrom .oracle_live_read_only_acquisition_runtime import (\n    CanonicalObservation,\n)\n\n\nSCHEMA_VERSION = "OLA-037"\nENGINE_ID = "OLA-037"\nRECEIPT_TYPE = "oracle_post_persistence_lineage_cycle_receipt"\n\nREAD_ONLY = True\nEXECUTION_ALLOWED = False\nEXECUTION_ADAPTER_RESOLVED = False\nEXECUTION_ADAPTER_INVOKED = False\nTRADE_AUTHORIZATION_ALLOWED = False\nORDER_PLACEMENT_ALLOWED = False\nFUNDS_MOVED = False\nPORTFOLIO_MUTATED = False\n\n\nclass PostPersistenceLineageCycleContractError(ValueError):\n    """Raised when OLA-037 coordination input is malformed."""\n\n\nclass PostPersistenceLineageCycleInvariantError(RuntimeError):\n    """Raised when OLA-037 permanent invariants are violated."""\n\n\ndef _require_utc_datetime(\n    value: Any,\n    field_name: str,\n) -> datetime:\n    if not isinstance(value, datetime):\n        raise PostPersistenceLineageCycleContractError(\n            f"{field_name} must be a datetime"\n        )\n    if value.tzinfo is None:\n        raise PostPersistenceLineageCycleContractError(\n            f"{field_name} must be timezone-aware"\n        )\n\n    return value.astimezone(timezone.utc)\n\n\ndef _require_non_empty_string(\n    value: Any,\n    field_name: str,\n) -> str:\n    if not isinstance(value, str):\n        raise PostPersistenceLineageCycleContractError(\n            f"{field_name} must be a string"\n        )\n\n    normalized = value.strip()\n\n    if not normalized:\n        raise PostPersistenceLineageCycleContractError(\n            f"{field_name} must not be empty"\n        )\n\n    return normalized\n\n\ndef _require_non_negative_int(\n    value: Any,\n    field_name: str,\n) -> int:\n    if isinstance(value, bool) or not isinstance(value, int):\n        raise PostPersistenceLineageCycleContractError(\n            f"{field_name} must be an integer"\n        )\n    if value < 0:\n        raise PostPersistenceLineageCycleContractError(\n            f"{field_name} must not be negative"\n        )\n\n    return value\n\n\ndef _stable_hash(value: Any) -> str:\n    encoded = json.dumps(\n        value,\n        sort_keys=True,\n        separators=(",", ":"),\n        ensure_ascii=False,\n        allow_nan=False,\n    ).encode("utf-8")\n\n    return sha256(encoded).hexdigest()\n\n\n@dataclass(frozen=True, slots=True)\nclass PersistedAcquisitionCycleEvidence:\n    schema_version: str\n    engine_id: str\n    cycle_status: str\n    acquisition_batch_id: str\n    canonical_count: int\n    persistence_count: int\n    cycle_completed_at: datetime\n    read_only: bool\n    execution_allowed: bool\n\n    @classmethod\n    def create(\n        cls,\n        *,\n        schema_version: str,\n        engine_id: str,\n        cycle_status: str,\n        acquisition_batch_id: str,\n        canonical_count: int,\n        persistence_count: int,\n        cycle_completed_at: datetime,\n        read_only: bool,\n        execution_allowed: bool,\n    ) -> "PersistedAcquisitionCycleEvidence":\n        record = cls(\n            schema_version=_require_non_empty_string(\n                schema_version,\n                "schema_version",\n            ),\n            engine_id=_require_non_empty_string(\n                engine_id,\n                "engine_id",\n            ),\n            cycle_status=_require_non_empty_string(\n                cycle_status,\n                "cycle_status",\n            ),\n            acquisition_batch_id=_require_non_empty_string(\n                acquisition_batch_id,\n                "acquisition_batch_id",\n            ),\n            canonical_count=_require_non_negative_int(\n                canonical_count,\n                "canonical_count",\n            ),\n            persistence_count=_require_non_negative_int(\n                persistence_count,\n                "persistence_count",\n            ),\n            cycle_completed_at=_require_utc_datetime(\n                cycle_completed_at,\n                "cycle_completed_at",\n            ),\n            read_only=read_only,\n            execution_allowed=execution_allowed,\n        )\n\n        record.assert_invariants()\n        return record\n\n    def assert_invariants(self) -> None:\n        if self.cycle_status != "completed":\n            raise PostPersistenceLineageCycleContractError(\n                "persisted cycle status must be completed"\n            )\n        if self.read_only is not True:\n            raise PostPersistenceLineageCycleInvariantError(\n                "persisted cycle lost read-only invariant"\n            )\n        if self.execution_allowed is not False:\n            raise PostPersistenceLineageCycleInvariantError(\n                "persisted cycle gained execution capability"\n            )\n        if self.canonical_count <= 0:\n            raise PostPersistenceLineageCycleContractError(\n                "canonical_count must be positive"\n            )\n        if self.persistence_count != self.canonical_count:\n            raise PostPersistenceLineageCycleContractError(\n                "persistence_count must equal canonical_count"\n            )\n\n\n@dataclass(frozen=True, slots=True)\nclass PostPersistenceLineageCycleReceipt:\n    schema_version: str\n    engine_id: str\n    receipt_type: str\n    upstream_schema_version: str\n    upstream_engine_id: str\n    acquisition_batch_id: str\n    canonical_count: int\n    persistence_count: int\n    cycle_completed_at: str\n    lineage_cycle_receipt: LiveAcquisitionLineageCycleReceipt\n    transition_count: int\n    lineage_market_count_after: int\n    lineage_record_count_after: int\n    read_only: bool\n    execution_allowed: bool\n    execution_adapter_resolved: bool\n    execution_adapter_invoked: bool\n    trade_authorization_allowed: bool\n    order_placement_allowed: bool\n    funds_moved: bool\n    portfolio_mutated: bool\n    coordination_hash: str\n\n    def assert_invariants(self) -> None:\n        if self.schema_version != SCHEMA_VERSION:\n            raise PostPersistenceLineageCycleInvariantError(\n                "schema version invariant violated"\n            )\n        if self.engine_id != ENGINE_ID:\n            raise PostPersistenceLineageCycleInvariantError(\n                "engine identity invariant violated"\n            )\n        if self.receipt_type != RECEIPT_TYPE:\n            raise PostPersistenceLineageCycleInvariantError(\n                "receipt type invariant violated"\n            )\n        if self.canonical_count <= 0:\n            raise PostPersistenceLineageCycleInvariantError(\n                "canonical count must be positive"\n            )\n        if self.persistence_count != self.canonical_count:\n            raise PostPersistenceLineageCycleInvariantError(\n                "persistence equality invariant violated"\n            )\n        if (\n            self.acquisition_batch_id\n            != self.lineage_cycle_receipt.acquisition_batch_id\n        ):\n            raise PostPersistenceLineageCycleInvariantError(\n                "acquisition batch binding invariant violated"\n            )\n        if (\n            self.canonical_count\n            != self.lineage_cycle_receipt.cohort_observation_count\n        ):\n            raise PostPersistenceLineageCycleInvariantError(\n                "canonical cohort count binding invariant violated"\n            )\n        if (\n            self.cycle_completed_at\n            != self.lineage_cycle_receipt.cycle_observed_at\n        ):\n            raise PostPersistenceLineageCycleInvariantError(\n                "cycle completion clock binding invariant violated"\n            )\n        if (\n            self.transition_count\n            != self.lineage_cycle_receipt.transition_count\n        ):\n            raise PostPersistenceLineageCycleInvariantError(\n                "transition count binding invariant violated"\n            )\n\n        authority = (\n            self.read_only,\n            self.execution_allowed,\n            self.execution_adapter_resolved,\n            self.execution_adapter_invoked,\n            self.trade_authorization_allowed,\n            self.order_placement_allowed,\n            self.funds_moved,\n            self.portfolio_mutated,\n        )\n\n        if authority != (\n            True,\n            False,\n            False,\n            False,\n            False,\n            False,\n            False,\n            False,\n        ):\n            raise PostPersistenceLineageCycleInvariantError(\n                "OLA-037 read-only authority invariants violated"\n            )\n\n\nclass OraclePostPersistenceLineageCycleCoordinator:\n    read_only = True\n    execution_allowed = False\n\n    def __init__(\n        self,\n        *,\n        lineage_cycle_bridge: (\n            OracleLiveAcquisitionLineageCycleBridge | None\n        ) = None,\n    ) -> None:\n        self._lineage_cycle_bridge = (\n            lineage_cycle_bridge\n            if lineage_cycle_bridge is not None\n            else OracleLiveAcquisitionLineageCycleBridge()\n        )\n\n        if not isinstance(\n            self._lineage_cycle_bridge,\n            OracleLiveAcquisitionLineageCycleBridge,\n        ):\n            raise PostPersistenceLineageCycleContractError(\n                "lineage_cycle_bridge must be an OLA-036 "\n                "OracleLiveAcquisitionLineageCycleBridge"\n            )\n\n    @property\n    def lineage_cycle_bridge(\n        self,\n    ) -> OracleLiveAcquisitionLineageCycleBridge:\n        return self._lineage_cycle_bridge\n\n    def coordinate(\n        self,\n        *,\n        cycle_evidence: PersistedAcquisitionCycleEvidence,\n        canonical_observations: Iterable[CanonicalObservation],\n    ) -> PostPersistenceLineageCycleReceipt:\n        if not isinstance(\n            cycle_evidence,\n            PersistedAcquisitionCycleEvidence,\n        ):\n            raise PostPersistenceLineageCycleContractError(\n                "cycle_evidence must be PersistedAcquisitionCycleEvidence"\n            )\n\n        cycle_evidence.assert_invariants()\n\n        observations = tuple(canonical_observations)\n\n        if not observations:\n            raise PostPersistenceLineageCycleContractError(\n                "canonical_observations must not be empty"\n            )\n\n        if len(observations) != cycle_evidence.canonical_count:\n            raise PostPersistenceLineageCycleContractError(\n                "supplied canonical observation count does not match "\n                "persisted cycle evidence"\n            )\n\n        batch_ids: set[str] = set()\n\n        for observation in observations:\n            if not isinstance(observation, CanonicalObservation):\n                raise PostPersistenceLineageCycleContractError(\n                    "all canonical_observations must be canonical"\n                )\n\n            if observation.observation_type != "market_snapshot":\n                raise PostPersistenceLineageCycleContractError(\n                    "OLA-037 accepts only market_snapshot observations"\n                )\n\n            batch_ids.add(\n                _require_non_empty_string(\n                    observation.acquisition_batch_id,\n                    "observation.acquisition_batch_id",\n                )\n            )\n\n        if batch_ids != {cycle_evidence.acquisition_batch_id}:\n            raise PostPersistenceLineageCycleContractError(\n                "canonical observation batch identity does not match "\n                "persisted cycle evidence"\n            )\n\n        before_record_count = (\n            self._lineage_cycle_bridge\n            .batch_router\n            .bridge\n            .ledger\n            .record_count\n        )\n\n        try:\n            lineage_receipt = (\n                self._lineage_cycle_bridge.advance_cycle(\n                    observations=observations,\n                    cycle_observed_at=(\n                        cycle_evidence.cycle_completed_at\n                    ),\n                )\n            )\n        except LiveAcquisitionLineageCycleContractError as exc:\n            raise PostPersistenceLineageCycleContractError(\n                f"OLA-036 lineage cycle rejected persisted cohort: {exc}"\n            ) from exc\n        except LiveAcquisitionLineageCycleInvariantError as exc:\n            raise PostPersistenceLineageCycleInvariantError(\n                f"OLA-036 lineage cycle invariant failed: {exc}"\n            ) from exc\n\n        expected_after_record_count = (\n            before_record_count\n            + cycle_evidence.canonical_count\n        )\n\n        if (\n            lineage_receipt.ledger_record_count_after\n            != expected_after_record_count\n        ):\n            raise PostPersistenceLineageCycleInvariantError(\n                "lineage record delta does not match persisted canonical count"\n            )\n\n        payload = {\n            "schema_version": SCHEMA_VERSION,\n            "engine_id": ENGINE_ID,\n            "receipt_type": RECEIPT_TYPE,\n            "upstream_schema_version": cycle_evidence.schema_version,\n            "upstream_engine_id": cycle_evidence.engine_id,\n            "acquisition_batch_id": (\n                cycle_evidence.acquisition_batch_id\n            ),\n            "canonical_count": cycle_evidence.canonical_count,\n            "persistence_count": cycle_evidence.persistence_count,\n            "cycle_completed_at": (\n                cycle_evidence.cycle_completed_at.isoformat()\n            ),\n            "lineage_cycle_receipt_hash": (\n                lineage_receipt.cycle_receipt_hash\n            ),\n            "transition_count": lineage_receipt.transition_count,\n            "lineage_market_count_after": (\n                lineage_receipt.ledger_market_count_after\n            ),\n            "lineage_record_count_after": (\n                lineage_receipt.ledger_record_count_after\n            ),\n            "read_only": READ_ONLY,\n            "execution_allowed": EXECUTION_ALLOWED,\n            "execution_adapter_resolved": EXECUTION_ADAPTER_RESOLVED,\n            "execution_adapter_invoked": EXECUTION_ADAPTER_INVOKED,\n            "trade_authorization_allowed": TRADE_AUTHORIZATION_ALLOWED,\n            "order_placement_allowed": ORDER_PLACEMENT_ALLOWED,\n            "funds_moved": FUNDS_MOVED,\n            "portfolio_mutated": PORTFOLIO_MUTATED,\n        }\n\n        receipt = PostPersistenceLineageCycleReceipt(\n            schema_version=SCHEMA_VERSION,\n            engine_id=ENGINE_ID,\n            receipt_type=RECEIPT_TYPE,\n            upstream_schema_version=cycle_evidence.schema_version,\n            upstream_engine_id=cycle_evidence.engine_id,\n            acquisition_batch_id=(\n                cycle_evidence.acquisition_batch_id\n            ),\n            canonical_count=cycle_evidence.canonical_count,\n            persistence_count=cycle_evidence.persistence_count,\n            cycle_completed_at=(\n                cycle_evidence.cycle_completed_at.isoformat()\n            ),\n            lineage_cycle_receipt=lineage_receipt,\n            transition_count=lineage_receipt.transition_count,\n            lineage_market_count_after=(\n                lineage_receipt.ledger_market_count_after\n            ),\n            lineage_record_count_after=(\n                lineage_receipt.ledger_record_count_after\n            ),\n            read_only=READ_ONLY,\n            execution_allowed=EXECUTION_ALLOWED,\n            execution_adapter_resolved=EXECUTION_ADAPTER_RESOLVED,\n            execution_adapter_invoked=EXECUTION_ADAPTER_INVOKED,\n            trade_authorization_allowed=TRADE_AUTHORIZATION_ALLOWED,\n            order_placement_allowed=ORDER_PLACEMENT_ALLOWED,\n            funds_moved=FUNDS_MOVED,\n            portfolio_mutated=PORTFOLIO_MUTATED,\n            coordination_hash=_stable_hash(payload),\n        )\n\n        receipt.assert_invariants()\n        return receipt\n'

TEST_SOURCE = 'from datetime import datetime, timezone\n\nfrom qseries_v2.oracle_intelligence.live_acquisition.oracle_post_persistence_lineage_cycle_coordinator import (\n    OraclePostPersistenceLineageCycleCoordinator,\n    PersistedAcquisitionCycleEvidence,\n    PostPersistenceLineageCycleContractError,\n)\nfrom qseries_v2.oracle_intelligence.live_acquisition.oracle_live_read_only_acquisition_runtime import (\n    CanonicalObservation,\n    RawSourceObservation,\n)\n\n\nT1 = datetime(2026, 7, 14, 10, 0, 0, tzinfo=timezone.utc)\nT2 = datetime(2026, 7, 14, 10, 0, 15, tzinfo=timezone.utc)\nT3 = datetime(2026, 7, 14, 10, 0, 30, tzinfo=timezone.utc)\n\n\ndef build_observation(\n    *,\n    market_id,\n    frame_id,\n    batch_id,\n    yes_ask="0.6140",\n):\n    payload = {\n        "source_market_id": market_id,\n        "yes_bid_dollars": "0.0000",\n        "yes_bid_size_fp": "0.00",\n        "yes_ask_dollars": yes_ask,\n        "yes_ask_size_fp": "40.00",\n        "no_bid_dollars": "0.3860",\n        "no_ask_dollars": "0.0000",\n        "last_price_dollars": "0.0000",\n        "previous_yes_bid_dollars": "0.0000",\n        "previous_yes_ask_dollars": "0.6000",\n        "previous_price_dollars": "0.0000",\n        "volume_fp": "0.00",\n        "volume_24h_fp": "0.00",\n        "open_interest_fp": "0.00",\n        "liquidity_dollars": "0.0000",\n    }\n\n    raw = RawSourceObservation.create(\n        source_observation_id=(\n            "kalshi." + market_id + "." + frame_id\n        ),\n        observed_at=T1,\n        observation_type="market_snapshot",\n        payload=payload,\n        provenance={\n            "source_id": "source.kalshi.market_data",\n            "frame_id": frame_id,\n        },\n    )\n\n    return CanonicalObservation.create(\n        source_id="source.kalshi.market_data",\n        raw_observation=raw,\n        acquired_at=T1,\n        acquisition_batch_id=batch_id,\n    )\n\n\ndef build_cycle(\n    *,\n    number,\n    completed_at,\n    changed_market=None,\n):\n    batch_id = f"batch.ola.037.{number}"\n    observations = []\n\n    for index in range(1, 6):\n        market_id = f"KXTEST-POST-PERSIST-{index}"\n\n        observations.append(\n            build_observation(\n                market_id=market_id,\n                frame_id=f"{number}-{index}",\n                batch_id=batch_id,\n                yes_ask=(\n                    "0.8300"\n                    if changed_market == market_id\n                    else "0.6140"\n                ),\n            )\n        )\n\n    evidence = PersistedAcquisitionCycleEvidence.create(\n        schema_version="OLA-017",\n        engine_id="OLA-017",\n        cycle_status="completed",\n        acquisition_batch_id=batch_id,\n        canonical_count=5,\n        persistence_count=5,\n        cycle_completed_at=completed_at,\n        read_only=True,\n        execution_allowed=False,\n    )\n\n    return evidence, tuple(observations)\n\n\ndef run_first_persisted_cycle_test():\n    coordinator = OraclePostPersistenceLineageCycleCoordinator()\n\n    evidence, observations = build_cycle(\n        number=1,\n        completed_at=T1,\n    )\n\n    receipt = coordinator.coordinate(\n        cycle_evidence=evidence,\n        canonical_observations=observations,\n    )\n\n    assert receipt.upstream_schema_version == "OLA-017"\n    assert receipt.upstream_engine_id == "OLA-017"\n    assert receipt.canonical_count == 5\n    assert receipt.persistence_count == 5\n    assert receipt.transition_count == 0\n    assert receipt.lineage_market_count_after == 5\n    assert receipt.lineage_record_count_after == 5\n\n    return coordinator, receipt\n\n\ndef run_repeated_persisted_cycle_test():\n    coordinator, _ = run_first_persisted_cycle_test()\n\n    evidence, observations = build_cycle(\n        number=2,\n        completed_at=T2,\n    )\n\n    receipt = coordinator.coordinate(\n        cycle_evidence=evidence,\n        canonical_observations=observations,\n    )\n\n    assert receipt.transition_count == 0\n    assert receipt.lineage_market_count_after == 5\n    assert receipt.lineage_record_count_after == 10\n\n    for item in (\n        receipt\n        .lineage_cycle_receipt\n        .lineage_batch_receipt\n        .receipts\n    ):\n        assert item.consecutive_frame_count == 2\n        assert item.dwell_seconds == "15.000000"\n\n    return coordinator, receipt\n\n\ndef run_persisted_change_cycle_test():\n    coordinator, _ = run_repeated_persisted_cycle_test()\n\n    evidence, observations = build_cycle(\n        number=3,\n        completed_at=T3,\n        changed_market="KXTEST-POST-PERSIST-2",\n    )\n\n    receipt = coordinator.coordinate(\n        cycle_evidence=evidence,\n        canonical_observations=observations,\n    )\n\n    assert receipt.transition_count == 1\n    assert receipt.lineage_record_count_after == 15\n\n    changed = [\n        item\n        for item in (\n            receipt\n            .lineage_cycle_receipt\n            .lineage_batch_receipt\n            .receipts\n        )\n        if item.transition_detected\n    ]\n\n    assert len(changed) == 1\n    assert changed[0].source_market_id == "KXTEST-POST-PERSIST-2"\n    assert changed[0].state_changed_at == T3.isoformat()\n\n    return receipt\n\n\ndef run_failed_persistence_evidence_test():\n    coordinator = OraclePostPersistenceLineageCycleCoordinator()\n\n    try:\n        PersistedAcquisitionCycleEvidence.create(\n            schema_version="OLA-017",\n            engine_id="OLA-017",\n            cycle_status="failed",\n            acquisition_batch_id="batch.failed",\n            canonical_count=5,\n            persistence_count=0,\n            cycle_completed_at=T1,\n            read_only=True,\n            execution_allowed=False,\n        )\n        raise AssertionError(\n            "failed persistence evidence must fail closed"\n        )\n    except PostPersistenceLineageCycleContractError:\n        pass\n\n    assert (\n        coordinator\n        .lineage_cycle_bridge\n        .batch_router\n        .bridge\n        .ledger\n        .record_count\n        == 0\n    )\n\n\ndef run_persistence_count_mismatch_test():\n    coordinator = OraclePostPersistenceLineageCycleCoordinator()\n\n    try:\n        PersistedAcquisitionCycleEvidence.create(\n            schema_version="OLA-017",\n            engine_id="OLA-017",\n            cycle_status="completed",\n            acquisition_batch_id="batch.mismatch",\n            canonical_count=5,\n            persistence_count=4,\n            cycle_completed_at=T1,\n            read_only=True,\n            execution_allowed=False,\n        )\n        raise AssertionError(\n            "persistence count mismatch must fail closed"\n        )\n    except PostPersistenceLineageCycleContractError:\n        pass\n\n    assert (\n        coordinator\n        .lineage_cycle_bridge\n        .batch_router\n        .bridge\n        .ledger\n        .record_count\n        == 0\n    )\n\n\ndef run_supplied_cohort_count_mismatch_test():\n    coordinator = OraclePostPersistenceLineageCycleCoordinator()\n    evidence, observations = build_cycle(\n        number=1,\n        completed_at=T1,\n    )\n\n    try:\n        coordinator.coordinate(\n            cycle_evidence=evidence,\n            canonical_observations=observations[:-1],\n        )\n        raise AssertionError(\n            "supplied cohort count mismatch must fail closed"\n        )\n    except PostPersistenceLineageCycleContractError:\n        pass\n\n    assert (\n        coordinator\n        .lineage_cycle_bridge\n        .batch_router\n        .bridge\n        .ledger\n        .record_count\n        == 0\n    )\n\n\ndef run_batch_identity_mismatch_test():\n    coordinator = OraclePostPersistenceLineageCycleCoordinator()\n    evidence, observations = build_cycle(\n        number=1,\n        completed_at=T1,\n    )\n\n    wrong = list(observations)\n    wrong[-1] = build_observation(\n        market_id="KXTEST-POST-PERSIST-5",\n        frame_id="wrong-batch",\n        batch_id="batch.other",\n    )\n\n    try:\n        coordinator.coordinate(\n            cycle_evidence=evidence,\n            canonical_observations=wrong,\n        )\n        raise AssertionError(\n            "batch identity mismatch must fail closed"\n        )\n    except PostPersistenceLineageCycleContractError:\n        pass\n\n    assert (\n        coordinator\n        .lineage_cycle_bridge\n        .batch_router\n        .bridge\n        .ledger\n        .record_count\n        == 0\n    )\n\n\ndef run_deterministic_coordination_replay_test():\n    first = OraclePostPersistenceLineageCycleCoordinator()\n    second = OraclePostPersistenceLineageCycleCoordinator()\n\n    cycles = (\n        build_cycle(number=1, completed_at=T1),\n        build_cycle(number=2, completed_at=T2),\n        build_cycle(\n            number=3,\n            completed_at=T3,\n            changed_market="KXTEST-POST-PERSIST-4",\n        ),\n    )\n\n    first_receipts = []\n    second_receipts = []\n\n    for evidence, observations in cycles:\n        first_receipts.append(\n            first.coordinate(\n                cycle_evidence=evidence,\n                canonical_observations=observations,\n            )\n        )\n        second_receipts.append(\n            second.coordinate(\n                cycle_evidence=evidence,\n                canonical_observations=observations,\n            )\n        )\n\n    assert first_receipts == second_receipts\n\n    first_records = (\n        first\n        .lineage_cycle_bridge\n        .batch_router\n        .bridge\n        .ledger\n        .records()\n    )\n    second_records = (\n        second\n        .lineage_cycle_bridge\n        .batch_router\n        .bridge\n        .ledger\n        .records()\n    )\n\n    assert first_records == second_records\n\n    return first_receipts\n\n\ndef main():\n    _, first = run_first_persisted_cycle_test()\n    _, second = run_repeated_persisted_cycle_test()\n    third = run_persisted_change_cycle_test()\n\n    run_failed_persistence_evidence_test()\n    run_persistence_count_mismatch_test()\n    run_supplied_cohort_count_mismatch_test()\n    run_batch_identity_mismatch_test()\n\n    replayed = run_deterministic_coordination_replay_test()\n\n    result = {\n        "schema_version": third.schema_version,\n        "engine_id": third.engine_id,\n        "status": "passed",\n        "successful_persistence_required_before_lineage": True,\n        "ola_017_cycle_identity_preserved": True,\n        "canonical_count_bound_to_persistence_count": True,\n        "exact_canonical_cohort_required": True,\n        "acquisition_batch_identity_bound": True,\n        "cycle_completion_time_bound_to_lineage": True,\n        "ola_036_lineage_cycle_bridge_consumed": True,\n        "first_five_market_persisted_cycle_advanced": (\n            first.lineage_record_count_after == 5\n        ),\n        "repeated_persisted_cycle_dwell_advanced": (\n            second.lineage_record_count_after == 10\n        ),\n        "persisted_real_change_transition_detected": (\n            third.transition_count == 1\n        ),\n        "failed_persistence_evidence_fails_closed": True,\n        "persistence_count_mismatch_fails_closed": True,\n        "supplied_cohort_count_mismatch_fails_closed": True,\n        "batch_identity_mismatch_fails_closed": True,\n        "lineage_not_mutated_on_precondition_failure": True,\n        "deterministic_coordination_replay_valid": (\n            len(replayed) == 3\n        ),\n        "no_acquisition_owned": True,\n        "no_persistence_owned": True,\n        "no_intelligence_interpretation": True,\n        "no_signal_scoring": True,\n        "alerts_allowed": False,\n        "qseries_handoff_allowed": False,\n        "read_only": third.read_only,\n        "execution_allowed": third.execution_allowed,\n        "execution_adapter_resolved": (\n            third.execution_adapter_resolved\n        ),\n        "execution_adapter_invoked": (\n            third.execution_adapter_invoked\n        ),\n        "trade_authorization_allowed": (\n            third.trade_authorization_allowed\n        ),\n        "order_placement_allowed": (\n            third.order_placement_allowed\n        ),\n        "funds_moved": third.funds_moved,\n        "portfolio_mutated": third.portfolio_mutated,\n    }\n\n    print(\n        "[PASS] OLA-037 Oracle Post-Persistence "\n        "Lineage Cycle Coordinator"\n    )\n    print(result)\n\n\nif __name__ == "__main__":\n    main()\n'


def write_full_replacement(path: Path, source: str) -> None:
    path.parent.mkdir(parents=True, exist_ok=True)
    path.write_text(source, encoding="utf-8", newline="\n")
    print(f"[OK] FULL REPLACEMENT: {path}")


